                    label="История"
                    icon={<ClockIcon className="w-6 h-6" />}
                    onClick={() => setShowArchive(true)}
                    colorClass="text-purple-600 dark:text-purple-400"
                 />
                 <CompactFooterButton 
                    label="Пригласить"
                    icon={<ShareIcon className="w-6 h-6" />}
                    onClick={handleInvite}
